export const INDIA = {
  d: "India packs deserts, rainforests, Himalayan passes, coral islands and thousands of years of living history into one country, and most of it is a short flight or an overnight train from Chennai. The trick is matching the region to the season: the hills of the south and the northeast shine after the monsoon, Rajasthan and the Golden Triangle are best in the cool months, and Ladakh and Spiti open only in summer.\n\nOur India itineraries are private and built around your dates. We handle hotels, a car and driver, trains or flights from Chennai, and the small details such as temple timings, permits for restricted areas and the best day of the week for markets.",
};

export const IN_REGIONS = [
  { s: "south-india", n: "South India", m: "karst", g: "#0b4f59,#1f9aa0,#ff8a3d", states: ["tamil-nadu", "kerala", "karnataka", "andhra-pradesh", "telangana", "puducherry"], d: "South India is our home ground. Temple towns with towering gopurams, the tea hills of Munnar and the Nilgiris, Kerala's backwaters and the boulder-strewn ruins of Hampi are all within a day's travel of Chennai.\n\nThe region is warm most of the year. October to March is the most comfortable time for the plains and coast, while the hill stations are a cool escape in April and May." },
  { s: "north-india", n: "North India", m: "peak", g: "#23305e,#4a6fb5,#a9c4ec", states: ["delhi", "uttar-pradesh", "rajasthan", "punjab", "himachal-pradesh", "uttarakhand", "jammu-and-kashmir", "ladakh"], d: "From the Mughal monuments of Delhi and Agra to the forts of Rajasthan and the snowfields of Kashmir, North India covers the classic first-time circuits and the high Himalaya.\n\nWinters (November to February) suit the plains and the desert, while summer is the season for Kashmir, Himachal, Uttarakhand and Ladakh. Many travellers combine both on separate trips." },
  { s: "west-india", n: "West India", m: "sea", g: "#0a6870,#2bb3a8,#ffa63b", states: ["goa", "maharashtra", "gujarat"], d: "West India mixes Goa's beaches and Portuguese-era churches with Mumbai's energy, the rock-cut caves of Ajanta and Ellora, and Gujarat's salt desert, lions and temple coast.\n\nNovember to February is the main season. The monsoon (June to September) turns the Western Ghats green and is a quiet, lower-priced time for hill retreats like Lonavala and Mahabaleshwar." },
  { s: "central-india", n: "Central India", m: "karst", g: "#123f36,#1c7a64,#6cc4a0", states: ["madhya-pradesh"], d: "Madhya Pradesh sits at the heart of the country and holds some of its best tiger reserves, the temple art of Khajuraho, the Buddhist stupas of Sanchi and the riverside city of Ujjain.\n\nThe parks open from October to June. Winter is the most comfortable time to travel, while March to May brings better tiger sightings as animals gather near water." },
  { s: "east-india", n: "East India", m: "temple", g: "#5a2a1e,#b3562b,#ff8a3d", states: ["west-bengal", "odisha", "bihar"], d: "East India is where Kolkata's colonial streets, the Sundarbans mangroves, the Sun Temple at Konark and the Buddhist sites of Bodh Gaya meet. Darjeeling's tea gardens add a cool Himalayan escape.\n\nOctober to March suits the plains and coast. Darjeeling is at its clearest in October–November and spring." },
  { s: "northeast-india", n: "Northeast India", m: "peak", g: "#1d4d3a,#2f8f6b,#9fd8b0", states: ["sikkim", "meghalaya", "assam", "arunachal-pradesh", "nagaland", "andaman-and-nicobar", "lakshadweep"], d: "The Northeast is India's least-visited corner and one of its most rewarding: living-root bridges in Meghalaya, one-horned rhinos at Kaziranga, monasteries in Sikkim and Tawang, and the Hornbill Festival in Nagaland. We also group India's two island territories, the Andamans and Lakshadweep, here because they are planned the same way, with permits and limited connections.\n\nOctober to April is the best window for most of the region. Some areas need an Inner Line Permit or Protected Area Permit, which we arrange." },
];

export const STATES = [
  { s: "tamil-nadu", n: "Tamil Nadu", cap: "Chennai", lang: "Tamil", t: "heritage pilgrimage hill beach", k: ["Dravidian temples", "Nilgiri hill stations", "Coromandel coast"], bt: ["October to March", "The plains are hot from April to June; that is when the Nilgiris and Kodaikanal are at their best."], d: "Tamil Nadu is home to some of the largest temple complexes on earth, from Madurai's Meenakshi Amman to the Chola temples around Thanjavur. Inland, the Nilgiris and Palani hills offer tea estates and cool weather, and the coast runs from the shore temples of Mahabalipuram to the southern tip at Kanyakumari.", go: "Chennai, Madurai, Coimbatore, Tiruchirappalli and Thoothukudi have airports. Trains link every major town, and a car with driver is the easiest way to string temples together.", tips: ["Most large temples ask men to remove shirts in the inner sanctum and everyone to remove footwear; carry socks for hot stone floors.", "Temple inner shrines usually close for a few hours in the early afternoon, so plan visits for the morning or evening."] },
  { s: "puducherry", n: "Puducherry", self: true, cap: "Puducherry", lang: "Tamil, French, English", ll: [11.93, 79.83], t: "heritage beach city food", k: ["French Quarter", "Auroville", "Seafront promenade"], bt: ["October to March", "Pleasant, dry days. The northeast monsoon brings heavy rain in November, usually in short bursts."], d: "Puducherry (Pondicherry) is a former French enclave three hours south of Chennai. Its White Town has mustard-yellow villas, bougainvillea and cafés, the Tamil quarter has old courtyard homes, and the experimental township of Auroville lies just outside the city.", go: "Most visitors drive from Chennai along the East Coast Road. Within town, walk or rent a bicycle in the French Quarter.", tips: ["The Rock Beach promenade closes to vehicles in the evening, which makes it a pleasant place for a walk.", "Book the Auroville Matrimandir viewing in advance; the inner chamber has limited slots."],
    a: [["French Quarter (White Town)", "Colonial villas, quiet lanes and cafés"], ["Promenade Beach", "Seafront walk along Goubert Avenue"], ["Auroville and the Matrimandir", "Experimental township with a golden meditation dome"], ["Sri Aurobindo Ashram", "Spiritual centre in the heart of town"], ["Paradise Beach", "Sandbar reached by a short boat ride from Chunnambar"]],
    ac: ["Heritage walks", "Cycling the French Quarter", "Café hopping", "Pottery and craft shopping", "Boat ride on the Chunnambar backwaters"], f: ["Creole-style prawn curry", "French bakery breads and croissants", "Fish moilee and Tamil seafood thalis"],
    r: ["Chennai International Airport (MAA), about 150 km; Puducherry airport has limited flights", "Puducherry railway station, with direct trains from Chennai Egmore", "About 3 hours from Chennai on the East Coast Road"], days: "2–3", tip: "Combine Puducherry with Mahabalipuram on the drive down from Chennai for an easy three-day coastal break.", b: "Couples, weekend breaks, heritage and food lovers" },
  { s: "kerala", n: "Kerala", cap: "Thiruvananthapuram", lang: "Malayalam", t: "backwater hill beach wildlife wellness", k: ["Backwaters", "Tea hills", "Ayurveda"], bt: ["September to March", "Post-monsoon greenery and dry, comfortable days. The monsoon (June to August) is the traditional season for Ayurveda treatments."], d: "Kerala packs tea-covered hills, spice plantations, wildlife reserves, houseboat-filled backwaters and palm-lined beaches into a narrow strip between the Western Ghats and the Arabian Sea. The classic route runs Kochi, Munnar, Thekkady and Alleppey, with Kovalam or Varkala added for the beach.", go: "Kochi and Thiruvananthapuram have the main airports; Kozhikode serves the north and Wayanad. Distances are short but hill roads are slow, so allow 3–4 hours for most transfers.", tips: ["Houseboat cruises usually start around noon and end the next morning; overnight stays have the boat moored at night by regulation.", "Carry light rain gear in any season; afternoon showers are common in the hills."] },
  { s: "karnataka", n: "Karnataka", cap: "Bengaluru", lang: "Kannada", t: "heritage hill wildlife beach", k: ["Hampi ruins", "Coffee country", "Mysuru palace"], bt: ["October to March", "Dry and pleasant. The monsoon turns Coorg and Chikmagalur lush but makes trekking slippery."], d: "Karnataka stretches from the Vijayanagara ruins at Hampi to the coffee estates of Coorg and Chikmagalur, the royal city of Mysuru and a quiet coastline at Gokarna and Udupi. Wildlife lovers head to Kabini and Bandipur for elephants and the chance of a leopard or tiger.", go: "Bengaluru is the main airport, with Mangaluru and Hubballi for the coast and north. Overnight trains reach Hospet (for Hampi) from Bengaluru.", tips: ["Mysuru Palace is lit with nearly 100,000 bulbs on Sunday and public-holiday evenings for a short window.", "Hampi is spread out; hire a guide for the first day and a bicycle or auto-rickshaw for the second."] },
  { s: "andhra-pradesh", n: "Andhra Pradesh", cap: "Amaravati", lang: "Telugu", t: "pilgrimage beach hill", k: ["Tirumala temple", "Araku Valley", "Vizag coast"], bt: ["October to March", "Comfortable temperatures along the coast and in the Eastern Ghats."], d: "Andhra Pradesh is best known for the Tirumala Venkateswara temple, one of the most visited pilgrimage sites in the world, but it also has the beaches and hills of Visakhapatnam, the coffee-growing Araku Valley and long stretches of the Bay of Bengal coast.", go: "Tirupati and Visakhapatnam have airports. The Kirandul line from Visakhapatnam to Araku is one of India's most scenic train rides.", tips: ["Book Tirumala darshan slots online well ahead; special-entry tickets sell out quickly in festival months.", "Choose the vistadome coach on the Araku train for glass-roof views through the tunnels."] },
  { s: "telangana", n: "Telangana", cap: "Hyderabad", lang: "Telugu, Urdu", t: "heritage city food", k: ["Charminar", "Golconda Fort", "Hyderabadi biryani"], bt: ["October to February", "Cool, dry winter days. Summers are very hot."], d: "Telangana centres on Hyderabad, a city of Qutb Shahi tombs, Nizami palaces, pearl markets and biryani, alongside a modern tech skyline. Beyond the capital, Warangal preserves the Kakatiya dynasty's temples and fort, including the UNESCO-listed Ramappa Temple.", go: "Rajiv Gandhi International Airport serves Hyderabad. Warangal is about three hours by road or train.", tips: ["Visit Golconda Fort in the late afternoon and stay for the evening sound-and-light show.", "Ramadan evenings in the Old City bring haleem stalls and night markets."] },
  { s: "goa", n: "Goa", cap: "Panaji", lang: "Konkani, English", t: "beach heritage nightlife food", k: ["Beaches", "Portuguese heritage", "Seafood"], bt: ["November to February", "Dry and sunny with calm seas. Many beach shacks close during the monsoon (June to September)."], d: "Goa is India's smallest state and its favourite beach holiday. North Goa has the busier beaches, markets and nightlife; South Goa is quieter, with long sandy beaches and resort stays. Between them, Old Goa's churches and the Latin Quarter of Panaji show four centuries of Portuguese influence.", go: "Goa has two airports: Dabolim in the south-centre and Manohar International at Mopa in the north. Hire a car with driver or a scooter; public transport is limited.", tips: ["Pick your base by mood: North Goa for buzz, South Goa for calm. The drive between them takes 1.5–2 hours.", "Christmas and New Year week is the most expensive time; early December and late January are better value."] },
  { s: "maharashtra", n: "Maharashtra", cap: "Mumbai", lang: "Marathi", t: "city heritage hill pilgrimage", k: ["Mumbai", "Ajanta & Ellora caves", "Sahyadri hill stations"], bt: ["October to February", "Dry and pleasant. Hill stations like Lonavala are at their greenest (and wettest) in the monsoon."], d: "Maharashtra combines Mumbai's colonial architecture and street food with the Buddhist and Hindu rock-cut caves of Ajanta and Ellora, hill stations in the Sahyadri ranges and the pilgrimage town of Shirdi.", go: "Mumbai and Pune have the main airports; Aurangabad (Chhatrapati Sambhajinagar) serves the caves. The Mumbai–Pune expressway connects to Lonavala.", tips: ["Ajanta is closed on Mondays and Ellora on Tuesdays, so plan the caves on two different days.", "Mumbai local trains are fast but crowded at rush hour; use a car for sightseeing."] },
  { s: "gujarat", n: "Gujarat", cap: "Gandhinagar", lang: "Gujarati", t: "heritage wildlife desert pilgrimage", k: ["Rann of Kutch", "Asiatic lions", "Temple coast"], bt: ["November to February", "Cool desert nights for the Rann Utsav and comfortable safari weather at Gir."], d: "Gujarat is the only place in the world where Asiatic lions live in the wild, at Gir. It also has the white salt desert of the Rann of Kutch, the old city of Ahmedabad (India's first UNESCO World Heritage City), the temples of Dwarka and Somnath, and the Statue of Unity.", go: "Ahmedabad is the main airport, with Bhuj, Rajkot and Kevadia for regional travel. Roads are good; plan full days for the long drives.", tips: ["Gir National Park is closed from mid-June to mid-October; safari permits sell out early for winter weekends.", "Gujarat is a dry state; alcohol permits are available for visitors at some hotels."] },
  { s: "rajasthan", n: "Rajasthan", cap: "Jaipur", lang: "Hindi, Rajasthani", t: "heritage desert culture", k: ["Forts and palaces", "Thar Desert", "Ranthambore tigers"], bt: ["October to March", "Cool, dry days for forts and desert camps. Summer (April to June) is extremely hot."], d: "Rajasthan is the land of maharajas: hilltop forts, lake palaces, painted havelis and the golden dunes of the Thar Desert. Jaipur, Udaipur, Jodhpur and Jaisalmer each have a distinct colour and character, and Ranthambore adds one of India's best tiger reserves.", go: "Jaipur, Udaipur, Jodhpur and Jaisalmer have airports. Distances are long, so most visitors travel by car with driver and use trains for longer hops.", tips: ["Book Ranthambore safari zones and gypsy/canter seats as early as possible; they open months ahead.", "Carry a scarf or jacket in winter; desert nights get cold even when the days are warm."] },
  { s: "delhi", n: "Delhi", self: true, cap: "New Delhi", lang: "Hindi, English, Punjabi, Urdu", ll: [28.61, 77.21], t: "city heritage food shopping", k: ["Mughal monuments", "Old Delhi bazaars", "Capital city"], bt: ["October to March", "Pleasant days; December and January bring cold mornings and occasional fog that can delay flights and trains."], d: "Delhi is two cities in one: the lanes of Old Delhi around the Jama Masjid and Chandni Chowk, and the broad avenues of Lutyens' New Delhi. Three UNESCO sites, Humayun's Tomb, the Qutub Minar and the Red Fort, make it the natural start of the Golden Triangle.", go: "The Delhi Metro reaches most sights and the airport; use a car for day trips and cycle-rickshaws in Old Delhi.", tips: ["Many monuments are closed on one weekday (the Red Fort on Mondays); check before planning.", "Air quality can be poor in late October and November; plan outdoor sightseeing for mid-morning."],
    a: [["Humayun's Tomb", "Garden tomb that inspired the Taj Mahal"], ["Qutub Minar", "Twelfth-century victory tower and ruins"], ["Red Fort and Chandni Chowk", "Mughal fort and the old city's main bazaar"], ["Jama Masjid", "One of India's largest mosques"], ["India Gate and Kartavya Path", "War memorial and ceremonial avenue"], ["Lotus Temple and Akshardham", "Modern landmarks of faith and design"]],
    ac: ["Old Delhi food walk", "Cycle-rickshaw ride", "Shopping at Dilli Haat", "Evening at Akshardham's water show", "Museum visits"], f: ["Chole bhature", "Parathas from Paranthe Wali Gali", "Kebabs near Jama Masjid", "Butter chicken"],
    r: ["Indira Gandhi International Airport (DEL)", "New Delhi, Old Delhi and Hazrat Nizamuddin stations connect the whole country", "National highways to Agra (Yamuna Expressway) and Jaipur"], days: "2–3", tip: "Start Old Delhi early, before the lanes fill up, and keep New Delhi's wide avenues for the afternoon.", b: "First-time visitors, history and food lovers" },
  { s: "uttar-pradesh", n: "Uttar Pradesh", cap: "Lucknow", lang: "Hindi, Urdu", t: "heritage pilgrimage culture", k: ["Taj Mahal", "Varanasi ghats", "Krishna's land"], bt: ["October to March", "Pleasant days; winter mornings can be foggy, which softens the light at the Taj and on the Ganga."], d: "Uttar Pradesh holds the Taj Mahal, the ancient riverside city of Varanasi, Krishna's birthplace at Mathura and Vrindavan, the newly rebuilt temple city of Ayodhya and the Nawabi culture of Lucknow. It is the spiritual and architectural heart of North India.", go: "Agra, Varanasi, Lucknow and Ayodhya have airports. The Yamuna Expressway links Delhi and Agra in about three and a half hours.", tips: ["The Taj Mahal is closed on Fridays; sunrise visits are the least crowded.", "In Varanasi, a boat on the Ganga at dawn is the single most memorable experience; book it for your first morning."] },
  { s: "himachal-pradesh", n: "Himachal Pradesh", cap: "Shimla", lang: "Hindi, Pahari", t: "hill mountain snow adventure", k: ["Hill stations", "Snow", "Spiti Valley"], bt: ["March to June and October to December", "Spring and autumn for clear views; December to February for snow in Shimla and Manali; June to September for Spiti and Lahaul."], d: "Himachal Pradesh runs from colonial Shimla to the Tibetan Buddhist valleys of Spiti and Lahaul. In between are Manali's apple orchards and snow points, the Dalai Lama's home at McLeod Ganj, and the riverside cafés of the Parvati Valley.", go: "Shimla, Kullu (Bhuntar) and Dharamshala (Gaggal) have small airports with limited flights; most visitors fly to Chandigarh and drive. The Kalka–Shimla toy train is a UNESCO-listed ride.", tips: ["The Atal Tunnel has made Lahaul reachable year-round from Manali, but heavy snow still closes roads; keep a buffer day in winter.", "Spiti needs time to acclimatise; avoid flying straight into altitude."] },
  { s: "uttarakhand", n: "Uttarakhand", cap: "Dehradun", lang: "Hindi, Garhwali, Kumaoni", t: "hill pilgrimage wildlife adventure mountain", k: ["Char Dham", "Rishikesh", "Corbett tigers"], bt: ["March to June and September to November", "Clear Himalayan views in autumn. The Char Dham temples open from about late April or May to October/November."], d: "Uttarakhand, the Devbhumi or land of the gods, holds the Char Dham pilgrimage, the yoga capital of Rishikesh, Haridwar's Ganga aarti, the lake town of Nainital, Mussoorie's ridge views, Jim Corbett's tiger reserve and ski slopes at Auli.", go: "Dehradun (Jolly Grant) is the main airport; Pantnagar serves the Kumaon hills. Overnight trains from Delhi reach Haridwar, Dehradun and Kathgodam.", tips: ["Kedarnath and Badrinath need online registration with the state government before travel.", "Monsoon landslides (July–August) often block mountain roads; avoid tight schedules then."] },
  { s: "punjab", n: "Punjab", cap: "Chandigarh", lang: "Punjabi", t: "pilgrimage heritage food culture", k: ["Golden Temple", "Wagah border", "Punjabi food"], bt: ["October to March", "Crisp winter days; fog can be heavy in late December and January."], d: "Punjab is the heartland of Sikhism and of North Indian food. Amritsar's Golden Temple feeds tens of thousands of people every day at its langar, the Wagah–Attari border ceremony is a spectacle of patriotism, and the countryside is a patchwork of wheat and mustard fields.", go: "Amritsar has an international airport and is well connected by train from Delhi, including the Shatabdi.", tips: ["Cover your head inside the Golden Temple complex; scarves are provided free at the entrance.", "Reach the Attari border ceremony early, especially on weekends."] },
  { s: "jammu-and-kashmir", n: "Jammu & Kashmir", cap: "Srinagar (summer), Jammu (winter)", lang: "Kashmiri, Dogri, Urdu", t: "hill snow lake honeymoon pilgrimage", k: ["Dal Lake", "Gulmarg snow", "Meadows"], bt: ["April to October; December to February for snow", "Spring tulips and summer meadows; winter brings skiing at Gulmarg."], d: "Kashmir's valley of lakes, meadows and pine forests is one of India's classic honeymoon and family destinations. Srinagar's houseboats and Mughal gardens, Gulmarg's gondola, Pahalgam's riverside meadows and Sonamarg's glacier views make a natural circuit, while Katra is the base for the Vaishno Devi pilgrimage.", go: "Srinagar and Jammu have airports. A car with driver is the usual way to travel within the valley.", tips: ["Prepaid mobile SIMs from other states may not work in J&K; postpaid connections usually do.", "Local taxi unions operate at Gulmarg, Pahalgam and Sonamarg for sightseeing beyond the main town; this is normal and included in most quotes."] },
  { s: "ladakh", n: "Ladakh", cap: "Leh", lang: "Ladakhi, Hindi", t: "mountain adventure lake desert", k: ["High passes", "Monasteries", "Pangong Lake"], bt: ["May to September", "Roads and passes open and days are warm; nights stay cold. Winter is for experienced travellers only."], d: "Ladakh is a high-altitude desert of monasteries, prayer flags and turquoise lakes on the far side of the Himalaya. Leh is the base for the Nubra Valley's sand dunes and Bactrian camels, Pangong Lake's changing blues and some of the highest motorable passes in the world.", go: "Fly to Leh and rest before driving higher. Inner Line Permits are needed for Nubra, Pangong and other border areas; we arrange them.", tips: ["Spend at least 36–48 hours in Leh before going higher to acclimatise; avoid alcohol and exertion on day one.", "Carry cash; ATMs and card machines are scarce beyond Leh."] },
  { s: "madhya-pradesh", n: "Madhya Pradesh", cap: "Bhopal", lang: "Hindi", t: "wildlife heritage pilgrimage", k: ["Tiger reserves", "Khajuraho temples", "Ujjain"], bt: ["October to March for comfort; March to May for tigers", "National parks open from mid-October to June."], d: "Madhya Pradesh is India's tiger state, with Kanha and Bandhavgarh among the best reserves in the country. It also holds the sculpted temples of Khajuraho, the Buddhist stupas at Sanchi, the fairy-tale town of Orchha, the Mahakaleshwar temple in Ujjain and the hill retreat of Pachmarhi.", go: "Bhopal, Indore, Jabalpur and Khajuraho have airports. Overnight trains are handy for the longer hops between parks.", tips: ["Core zones of the tiger reserves close one day a week (usually Wednesday afternoon) and during the monsoon.", "Combine Khajuraho with Orchha; they are about four hours apart by road."] },
  { s: "west-bengal", n: "West Bengal", cap: "Kolkata", lang: "Bengali", t: "city hill wildlife heritage food", k: ["Kolkata", "Darjeeling tea", "Sundarbans"], bt: ["October to March", "Comfortable in Kolkata and the Sundarbans; October–November gives the clearest Kanchenjunga views from Darjeeling."], d: "West Bengal stretches from the Bay of Bengal's mangrove forests to the Himalayan foothills. Kolkata is India's cultural capital, with colonial landmarks and the country's best sweets; Darjeeling and Kalimpong offer tea gardens and mountain views; the Sundarbans is home to the swimming Royal Bengal tiger.", go: "Kolkata is the main airport; Bagdogra serves Darjeeling and Sikkim. The Darjeeling Himalayan Railway toy train is UNESCO-listed.", tips: ["Durga Puja (September/October) transforms Kolkata; book hotels early if you want to see the pandals.", "Darjeeling's toy train joy ride from Darjeeling to Ghum is the easiest way to experience the line."] },
  { s: "odisha", n: "Odisha", cap: "Bhubaneswar", lang: "Odia", t: "heritage pilgrimage beach lake", k: ["Konark Sun Temple", "Puri Jagannath", "Chilika Lake"], bt: ["October to March", "Cool and dry; Chilika's migratory birds peak from December to February."], d: "Odisha's golden triangle of Bhubaneswar, Puri and Konark holds hundreds of Kalinga-style temples, the Jagannath temple and the UNESCO-listed Sun Temple. Chilika, Asia's largest brackish-water lagoon, hosts Irrawaddy dolphins and huge flocks of winter birds.", go: "Bhubaneswar is the main airport; Puri and Konark are an hour or so by road.", tips: ["Non-Hindus are not allowed inside the Jagannath temple at Puri; the Raghunandan Library rooftop nearby offers a view.", "The Rath Yatra (June or July) draws enormous crowds to Puri; book a year ahead."] },
  { s: "bihar", n: "Bihar", cap: "Patna", lang: "Hindi, Maithili, Bhojpuri", t: "pilgrimage heritage", k: ["Bodh Gaya", "Nalanda", "Buddhist circuit"], bt: ["October to March", "Pleasant winter days and the main pilgrimage season, especially December and January."], d: "Bihar is where the Buddha attained enlightenment and where ancient India's great university at Nalanda flourished. Bodh Gaya, Rajgir and Nalanda form the core of the Buddhist circuit, visited by pilgrims from across Asia.", go: "Gaya and Patna have airports. Bodh Gaya is about 15 km from Gaya, and Rajgir and Nalanda are 2–3 hours away by road.", tips: ["Winter is peak season for Buddhist pilgrims, especially around December–January teachings; book early.", "Dress modestly and walk clockwise around the stupas at Bodh Gaya."] },
  { s: "sikkim", n: "Sikkim", cap: "Gangtok", lang: "Nepali, Sikkimese, Lepcha", t: "mountain hill snow lake", k: ["Kanchenjunga views", "Monasteries", "High lakes"], bt: ["March to May and October to December", "Rhododendrons bloom in spring; autumn brings the clearest mountain views."], d: "Sikkim is a small Himalayan state with big views of Kanchenjunga, the world's third-highest peak. Gangtok is the lively capital, Pelling faces the mountain across the valley, and North Sikkim's Lachung and Yumthang lead to high-altitude lakes and snow.", go: "Fly to Bagdogra (or Pakyong, with limited flights) and drive 4–5 hours to Gangtok. Permits are needed for North Sikkim, Tsomgo Lake and Nathula; we arrange them.", tips: ["Plastic water bottles are restricted in parts of Sikkim; carry a refillable bottle.", "Nathula Pass is closed to visitors on Mondays and Tuesdays."] },
  { s: "meghalaya", n: "Meghalaya", cap: "Shillong", lang: "Khasi, Garo, English", t: "nature hill adventure", k: ["Living root bridges", "Waterfalls", "Clear rivers"], bt: ["October to April", "Dry trekking weather. The monsoon makes waterfalls spectacular but trails slippery."], d: "Meghalaya, the abode of clouds, is a plateau of pine hills, deep gorges and some of the wettest places on earth. Shillong is the base, Sohra (Cherrapunji) has living root bridges and waterfalls, and Dawki's Umngot River is famous for water so clear the boats seem to float.", go: "Guwahati airport is about three hours by road from Shillong. Shared and private taxis connect the main towns.", tips: ["The double-decker root bridge at Nongriat involves around 3,000 steps each way; start early and wear good shoes.", "Mawlynnong, often called Asia's cleanest village, pairs well with a Dawki day trip."] },
  { s: "assam", n: "Assam", cap: "Dispur", lang: "Assamese", t: "wildlife nature culture", k: ["Kaziranga rhinos", "Tea gardens", "Brahmaputra"], bt: ["November to April", "Kaziranga is open from November to April; the park closes in the monsoon."], d: "Assam is the gateway to the Northeast and the land of the Brahmaputra. Kaziranga National Park protects the world's largest population of one-horned rhinos, Majuli is one of the largest river islands on earth, and tea estates roll across the upper valley.", go: "Guwahati is the main airport and rail hub. Kaziranga is about 4–5 hours by road.", tips: ["Book an early-morning elephant or jeep safari at Kaziranga; the light and wildlife activity are best at dawn.", "Bihu festivals in April and January are a lively time to visit."] },
  { s: "arunachal-pradesh", n: "Arunachal Pradesh", cap: "Itanagar", lang: "English, Hindi and many tribal languages", t: "mountain culture adventure", k: ["Tawang Monastery", "Ziro Valley", "Tribal culture"], bt: ["October to April", "Clear skies and dry roads; snow on the high passes from December."], d: "Arunachal Pradesh is India's easternmost state, with snow-capped passes, Tibetan Buddhist monasteries and more than twenty major tribal communities. Tawang's monastery is the largest in India, and the Ziro Valley's rice fields host a well-known music festival.", go: "Indian visitors need an Inner Line Permit (we arrange it). Guwahati or Tezpur are the usual gateways for Tawang; Itanagar's Donyi Polo airport serves Ziro.", tips: ["The Sela Pass road to Tawang can close after snowfall; keep a spare day in winter.", "The drive to Tawang takes two days each way, so plan at least seven days for the trip."] },
  { s: "nagaland", n: "Nagaland", cap: "Kohima", lang: "English, Nagamese", t: "culture festival hill", k: ["Hornbill Festival", "Naga heritage", "Dzukou Valley"], bt: ["October to May; early December for Hornbill", "Cool, clear weather. The Hornbill Festival fills hotels in early December."], d: "Nagaland is home to sixteen major Naga tribes, each with its own dress, songs and food. The Hornbill Festival at Kisama near Kohima brings them together every December, and the rest of the year Kohima's war cemetery and the Dzukou Valley treks draw quieter visitors.", go: "Dimapur has the nearest airport and railhead; Kohima is about three hours by road. Indian visitors need an Inner Line Permit.", tips: ["Book Hornbill Festival stays months in advance; homestays and campsites fill up fastest.", "Naga cuisine uses smoked meats and the very hot raja mircha chilli; ask for milder versions."] },
  { s: "andaman-and-nicobar", n: "Andaman & Nicobar Islands", cap: "Sri Vijaya Puram (Port Blair)", lang: "Hindi, Bengali, Tamil, English", t: "island beach adventure honeymoon", k: ["Coral beaches", "Scuba diving", "Cellular Jail"], bt: ["October to May", "Calm seas and clear water for diving and ferries. The monsoon (June to September) cancels some sailings."], d: "The Andaman Islands sit in the Bay of Bengal closer to Myanmar than to mainland India. White beaches, coral reefs and rainforest make them India's best island holiday, with Havelock (Swaraj Dweep) and Neil (Shaheed Dweep) a short ferry from the capital.", go: "Flights from Chennai take about two hours. Government and private ferries link the islands; we pre-book private ferry seats.", tips: ["Ferries are weather-dependent; avoid booking your flight home on the same day you return from Havelock.", "Carry cash for the islands; card machines and ATMs can be unreliable outside the capital."] },
  { s: "lakshadweep", n: "Lakshadweep", cap: "Kavaratti", lang: "Malayalam, Jeseri", t: "island beach adventure", k: ["Coral atolls", "Lagoons", "Snorkelling"], bt: ["October to May", "Calm lagoons and clear water; the monsoon brings rough seas."], d: "Lakshadweep is a chain of coral atolls in the Arabian Sea off the Kerala coast, with lagoons so clear you can see the reef from the boat. Tourism is tightly controlled to protect the islands, so trips are planned around permits and a small number of approved stays.", go: "Fly from Kochi to Agatti, the only airport. All visitors need an entry permit from the Lakshadweep administration; we apply on your behalf.", tips: ["Alcohol is not available on most inhabited islands.", "Permit processing can take several weeks; start planning at least a month ahead."] },
];

